css:
.cert-page {
  position: relative;
  width: 297mm;
  height: 210mm;
  overflow: hidden;
  margin: 0;
  padding: 0;
  font-family: "Segoe UI", Arial, sans-serif;
}
.cert-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: fill;
}
.cert-name {
  position: absolute;
  top: 49%;
  left: 12%;
  right: 12%;
  text-align: center;
  font-size: 28pt;
  font-weight: 700;
  color: #1a1a1a;
  line-height: 1.2;
  letter-spacing: 0.02em;
}
.cert-date {
  position: absolute;
  left: 11%;
  bottom: 14.5%;
  width: 18%;
  text-align: center;
  font-size: 11pt;
  font-weight: 600;
  color: #1a1a1a;
}
